function control(state) {
  var tol = (state && typeof state.tolerancePx === 'number') ? state.tolerancePx : 7;
  var tip = state.tip;
  var tgt = state.target;
  var ex = tgt[0] - tip[0];
  var ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: 'stop', reason: 'non-finite error' };
  if (err <= tol) return { action: 'verify' };

  var hist = state.history || [];
  var n = hist.length;
  var S00 = 0, S01 = 0, S11 = 0;
  var R00 = 0, R01 = 0, R10 = 0, R11 = 0;
  var cnt = 0, exc0 = 0, exc1 = 0;
  var bp = [false, false];
  var bn = [false, false];

  for (var i = 0; i < n; i++) {
    var h = hist[i];
    if (!h || !h.applied || !h.delta || !h.command) continue;
    var a = h.applied[0], b = h.applied[1], dx = h.delta[0], dy = h.delta[1];
    var c0 = h.command[0], c1 = h.command[1];
    var vals = [a, b, dx, dy, c0, c1];
    var ok = true;
    for (var k = 0; k < 6; k++) {
      if (typeof vals[k] !== 'number' || !isFinite(vals[k])) { ok = false; break; }
    }
    if (!ok) continue;

    // 最近幾步內，指令大於實際接受量者視為該通道在該方向受行程限制
