      if (c0 !== 0 && Math.abs(a) < Math.abs(c0) - 1e-6) {
        if (c0 > 0) bp[0] = true; else bn[0] = true;
      }
      if (c1 !== 0 && Math.abs(b) < Math.abs(c1) - 1e-6) {
        if (c1 > 0) bp[1] = true; else bn[1] = true;
      }
    }

    var w = Math.pow(0.9, n - 1 - i);
    S00 += w * a * a;
    S01 += w * a * b;
    S11 += w * b * b;
    R00 += w * dx * a;
    R01 += w * dx * b;
    R10 += w * dy * a;
    R11 += w * dy * b;
    cnt++;
    exc0 += Math.abs(a);
    exc1 += Math.abs(b);
  }

  var freeOK = function (c, s) {
    return s > 0 ? !bp[c] : !bn[c];
  };

  var probe = function () {
    var order = (exc0 <= exc1) ? [0, 1] : [1, 0];
    for (var q = 0; q < 2; q++) {
      var c = order[q];
      var u = [0, 0];
      if (freeOK(c, 1)) { u[c] = 0.1; return { action: 'move', u: u }; }
      if (freeOK(c, -1)) { u[c] = -0.1; return { action: 'move', u: u }; }
    }
    return { action: 'stop', reason: 'both channels blocked' };
  };

  var det = S00 * S11 - S01 * S01;
  var sc = S00 + S11;
  if (cnt < 2 || !(sc > 0) || !(det > 1e-6 * sc * sc)) return probe();

  var Si00 = S11 / det, Si01 = -S01 / det, Si10 = -S01 / det, Si11 = S00 / det;
  var J00 = R00 * Si00 + R01 * Si10;
  var J01 = R00 * Si01 + R01 * Si11;
  var J10 = R10 * Si00 + R11 * Si10;
  var J11 = R10 * Si01 + R11 * Si11;
  var jd = J00 * J11 - J01 * J10;
  var jscale = Math.abs(J00) + Math.abs(J01) + Math.abs(J10) + Math.abs(J11);
