    gx = gx / Sc;
    gy = gy / Sc;
    var gg = gx * gx + gy * gy;
    if (!(gg > 1e-12)) return probe();
    var uc = (gx * ex + gy * ey) / gg;
    if (!isFinite(uc) || uc === 0) return probe();
