  var s = 1;
  if (m > 0.1) s = 0.1 / m;
  if (err < 40) s *= 0.7;
  u0 *= s;
  u1 *= s;

  var q0 = Math.round(u0 * 10000) / 10000;
  var q1 = Math.round(u1 * 10000) / 10000;
  if (q0 > 0.1) q0 = 0.1;
  if (q0 < -0.1) q0 = -0.1;
  if (q1 > 0.1) q1 = 0.1;
  if (q1 < -0.1) q1 = -0.1;
  if (q0 === 0 && q1 === 0) return probe();
  return { action: 'move', u: [q0, q1] };
}

