    return { action: 'move', u: dirs[h.length % 4] };
  }
  var Ji = [[J[1][1] / detJ, -J[0][1] / detJ], [-J[1][0] / detJ, J[0][0] / detJ]];
  var u0 = 0.8 * (Ji[0][0] * ex + Ji[0][1] * ey);
  var u1 = 0.8 * (Ji[1][0] * ex + Ji[1][1] * ey);
  if (!isFinite(u0) || !isFinite(u1)) return { action: 'stop', reason: 'bad solve' };
  var m = Math.max(Math.abs(u0), Math.abs(u1));
