  if (Math.abs(u1) > 0.1) u1 = u1 > 0 ? 0.1 : -0.1;
  return { action: 'move', u: [u0, u1] };
}

function control(state) {
  var tol = state.tolerancePx;
  var tip = state.tip;
  var target = state.target;
  var ex = target[0] - tip[0];
  var ey = target[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: "stop", reason: "non-finite error" };
  if (err <= tol) return { action: "verify" };

  var h = state.history || [];
  var start = Math.max(0, h.length - 12);
  var S00 = 0, S01 = 0, S11 = 0;
  var P0 = [0, 0], P1 = [0, 0];
  var n = 0;
