    return probe();
  }
  // J = Sdu * inv(S)
  var J00 = (Sdu00 * s11 - Sdu01 * s01) / sdet;
  var J01 = (-Sdu00 * s01 + Sdu01 * s00) / sdet;
  var J10 = (Sdu10 * s11 - Sdu11 * s01) / sdet;
  var J11 = (-Sdu10 * s01 + Sdu11 * s00) / sdet;
  var jd = J00 * J11 - J01 * J10;
  var jn = Math.sqrt(J00 * J00 + J01 * J01 + J10 * J10 + J11 * J11);
  if (!isFinite(jd) || !isFinite(jn) || jn < 1e-6 || Math.abs(jd) < 1e-3 * jn * jn) {
    return probe();
  }
  // u = inv(J) * e
  var u0 = (J11 * ex - J01 * ey) / jd;
  var u1 = (-J10 * ex + J00 * ey) / jd;
  u0 *= 0.5;
  u1 *= 0.5;
  if (!isFinite(u0) || !isFinite(u1)) {
    return probe();
  }
  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m > LIM) {
    u0 = u0 * LIM / m;
    u1 = u1 * LIM / m;
  }
  var v = allowed([u0, u1]);
  if (Math.abs(v[0]) < 1e-6 && Math.abs(v[1]) < 1e-6) {
    return probe();
  }
  return { action: 'move', u: v };
}
